package dev.rodrigo.biometriclab;

import android.os.*; import android.security.keystore.*; import android.util.Base64; import android.widget.*; import androidx.annotation.NonNull; import androidx.biometric.BiometricManager; import androidx.biometric.BiometricPrompt; import androidx.core.content.ContextCompat; import androidx.fragment.app.FragmentActivity; import java.security.KeyStore; import javax.crypto.*; import javax.crypto.spec.IvParameterSpec; import javax.crypto.SecretKey;

public class MainActivity extends FragmentActivity {
 private static final String ALIAS="biometric-lab-key", PREF="vault"; private EditText input; private TextView status; private BiometricPrompt prompt; private BiometricPrompt.PromptInfo info; private boolean decrypting;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);input=findViewById(R.id.input);status=findViewById(R.id.status);prompt=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(@NonNull BiometricPrompt.AuthenticationResult r){BiometricPrompt.CryptoObject o=r.getCryptoObject();Cipher c=o==null?null:o.getCipher();if(c==null){status.setText("No cipher returned");return;}try{if(decrypting){byte[] enc=Base64.decode(getPreferences().getString("cipher",""),Base64.NO_WRAP);String plain=new String(c.doFinal(enc),java.nio.charset.StandardCharsets.UTF_8);input.setText(plain);status.setText("Decrypted after biometric authentication");}else{byte[] enc=c.doFinal(input.getText().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));getPreferences().edit().putString("cipher",Base64.encodeToString(enc,Base64.NO_WRAP)).putString("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).apply();input.setText("");status.setText("Encrypted; only IV + ciphertext stored");}}catch(Exception e){status.setText("Crypto error: "+e.getMessage());}}@Override public void onAuthenticationError(int code,@NonNull CharSequence msg){status.setText("Authentication error: "+msg);}@Override public void onAuthenticationFailed(){status.setText("Biometric not recognized");}});info=new BiometricPrompt.PromptInfo.Builder().setTitle("Unlock cryptographic operation").setSubtitle("Use a strong biometric").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG).setNegativeButtonText("Cancel").build();findViewById(R.id.encrypt).setOnClickListener(v->beginEncrypt());findViewById(R.id.decrypt).setOnClickListener(v->beginDecrypt());findViewById(R.id.reset).setOnClickListener(v->reset());showCapability();}
 private android.content.SharedPreferences getPreferences(){return getSharedPreferences(PREF,MODE_PRIVATE);} private void showCapability(){int c=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG);status.setText(c==BiometricManager.BIOMETRIC_SUCCESS?"Strong biometric available":"Strong biometric unavailable/error code "+c);}
 private void ensureKey() throws Exception {KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return;KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");KeyGenParameterSpec.Builder b=new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_CBC).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_PKCS7).setUserAuthenticationRequired(true);if(Build.VERSION.SDK_INT>=30)b.setUserAuthenticationParameters(0,KeyProperties.AUTH_BIOMETRIC_STRONG);else b.setUserAuthenticationValidityDurationSeconds(-1);if(Build.VERSION.SDK_INT>=24)b.setInvalidatedByBiometricEnrollment(true);g.init(b.build());g.generateKey();}
 private SecretKey key() throws Exception {KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);return (SecretKey)ks.getKey(ALIAS,null);} private Cipher cipher() throws Exception{return Cipher.getInstance("AES/CBC/PKCS7Padding");}
 private void beginEncrypt(){if(input.getText().length()==0){status.setText("Enter text to encrypt");return;}try{ensureKey();Cipher c=cipher();c.init(Cipher.ENCRYPT_MODE,key());decrypting=false;prompt.authenticate(info,new BiometricPrompt.CryptoObject(c));}catch(Exception e){status.setText("Cannot start encryption: "+e.getClass().getSimpleName()+": "+e.getMessage());}}
 private void beginDecrypt(){String iv=getPreferences().getString("iv","");String enc=getPreferences().getString("cipher","");if(iv.isEmpty()||enc.isEmpty()){status.setText("No ciphertext stored yet");return;}try{ensureKey();Cipher c=cipher();c.init(Cipher.DECRYPT_MODE,key(),new IvParameterSpec(Base64.decode(iv,Base64.NO_WRAP)));decrypting=true;prompt.authenticate(info,new BiometricPrompt.CryptoObject(c));}catch(Exception e){status.setText("Cannot start decryption: "+e.getClass().getSimpleName()+": "+e.getMessage());}}
 private void reset(){try{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))ks.deleteEntry(ALIAS);getPreferences().edit().clear().apply();status.setText("Key and demo ciphertext deleted");}catch(Exception e){status.setText("Reset error: "+e.getMessage());}}
}